-- Заказанный пакет 300 RU→EN / 400 EN→RU / 300 RU→KK.
-- V54 и её исходные JSON неизменны. Новые опубликованные редакции и игры
-- доставляются обычной миграцией, без Java-загрузчика и локальных аккаунтов.
-- actor/reviewed_by = NULL: системная поставка не изображает человеческую проверку.
-- Ссылки нужны для вычитки; независимая лингвистическая приёмка не заявляется.
-- Уже опубликованные, архивные или изменённые редактором банки не перезаписываются.

create table quiz_v57_banks (
    code varchar(96) primary key, expected_count integer not null,
    original_title_ru varchar(255), original_title_kk varchar(255),
    title_ru varchar(255), title_kk varchar(255), source_reference text,
    description_ru text, description_kk text, card_style varchar(32), catalog_order integer
);

-- Эти таблицы содержат только данные поставки и удаляются в конце миграции.
create table quiz_v57_words (
    code varchar(96), source_text varchar(512), original_primary varchar(512),
    primary_answer varchar(512), source_reference text, part_of_speech varchar(64),
    meaning_note_ru text, difficulty integer, primary key(code, source_text)
);

-- Выбираем только нетронутые банки V54 целиком; иначе сохраняем решение редактора.
create table quiz_v57_ready (set_id bigint primary key);
select s.id from vocabulary_sets s
join quiz_v57_banks b on b.code=s.code
join vocabulary_set_versions v on v.id=s.draft_version_id
where s.status='DRAFT' and s.published_version_id is null and s.created_by is null
  and v.version_no=1 and v.status='DRAFT' and v.source_reference=''
  and v.title_ru=b.original_title_ru and v.title_kk=b.original_title_kk
  and v.cross_set_distractors_allowed=false
  and (select count(*) from vocabulary_set_versions x where x.set_id=s.id)=1
  and (select count(*) from vocabulary_items i where i.set_id=s.id)=b.expected_count
  and (select count(*) from vocabulary_items i
       join vocabulary_item_versions x on x.id=i.draft_version_id
       join vocabulary_item_answers a on a.item_version_id=x.id and a.is_primary=true
       join quiz_v57_words w on w.code=s.code and w.source_text=x.source_text
       where i.set_id=s.id and i.status='DRAFT' and i.published_version_id is null
         and i.created_by is null and x.version_no=1 and x.status='DRAFT'
         and x.source_reference='' and x.universal_audience=true
         and x.part_of_speech=w.part_of_speech and x.meaning_note_ru=w.meaning_note_ru
         and x.difficulty=w.difficulty and a.answer_text=w.original_primary
         and (select count(*) from vocabulary_item_versions y where y.item_id=i.id)=1
         and not exists(select 1 from vocabulary_item_grades g where g.item_version_id=x.id)
      )=b.expected_count;

select s.id,2,'PUBLISHED',v.title_ru,v.title_kk,b.source_reference,false,current_timestamp,current_timestamp
from quiz_v57_ready r join vocabulary_sets s on s.id=r.set_id
join vocabulary_set_versions v on v.id=s.draft_version_id join quiz_v57_banks b on b.code=s.code;

     meaning_note_ru,meaning_note_kk,difficulty,source_reference,universal_audience,published_at,reviewed_at)
select i.id,2,'PUBLISHED',v.source_text,v.source_normalized,v.pronunciation,v.part_of_speech,
       v.meaning_note_ru,v.meaning_note_kk,v.difficulty,w.source_reference,true,current_timestamp,current_timestamp
from quiz_v57_ready r join vocabulary_sets s on s.id=r.set_id
join vocabulary_items i on i.set_id=s.id join vocabulary_item_versions v on v.id=i.draft_version_id
join quiz_v57_words w on w.code=s.code and w.source_text=v.source_text;

-- Исправление «страница» → «бет» относится только к новой редакции; старый ключ сохраняется.
select n.id,case when a.is_primary then w.primary_answer else a.answer_text end,
       case when a.is_primary and w.primary_answer<>w.original_primary then lower(w.primary_answer)
            else a.answer_normalized end,a.is_primary,a.primary_marker
from quiz_v57_ready r join vocabulary_sets s on s.id=r.set_id
join vocabulary_items i on i.set_id=s.id join vocabulary_item_versions v on v.id=i.draft_version_id
join vocabulary_item_versions n on n.item_id=i.id and n.version_no=2
join vocabulary_item_answers a on a.item_version_id=v.id
join quiz_v57_words w on w.code=s.code and w.source_text=v.source_text;

select 'VOCABULARY_ITEM',i.id,v.id,'DRAFT','PUBLISHED' from vocabulary_items i
join quiz_v57_ready r on r.set_id=i.set_id join vocabulary_item_versions v on v.item_id=i.id and v.version_no=2;
select 'VOCABULARY_SET',r.set_id,v.id,'DRAFT','PUBLISHED' from quiz_v57_ready r
join vocabulary_set_versions v on v.set_id=r.set_id and v.version_no=2;

update vocabulary_items set status='PUBLISHED',draft_version_id=null,
    published_version_id=(select v.id from vocabulary_item_versions v where v.item_id=vocabulary_items.id and v.version_no=2),
    updated_at=current_timestamp where set_id in (select set_id from quiz_v57_ready);
update vocabulary_sets set status='PUBLISHED',draft_version_id=null,
    published_version_id=(select v.id from vocabulary_set_versions v where v.set_id=vocabulary_sets.id and v.version_no=2),
    updated_at=current_timestamp where id in (select set_id from quiz_v57_ready);

-- Три карточки используют реальные опубликованные банки. Чужие игры с тем же кодом сохраняются.
create table quiz_v57_games (code varchar(96) primary key, game_id bigint);
select b.code from quiz_v57_banks b join vocabulary_sets s on s.code=b.code
where s.status='PUBLISHED' and s.published_version_id is not null
  and not exists(select 1 from quiz_games g where g.code=b.code)
  and (select count(*) from vocabulary_items i join vocabulary_item_versions v on v.id=i.published_version_id
       where i.set_id=s.id and i.status='PUBLISHED' and v.status='PUBLISHED' and v.universal_audience=true)=b.expected_count;
select code,'PUBLISHED',true from quiz_v57_games;
update quiz_v57_games set game_id=(select g.id from quiz_games g where g.code=quiz_v57_games.code);

     mechanic_label_ru,mechanic_label_kk,card_style,catalog_order,grade_selection_mode,audience_policy,
     default_question_count,min_question_count,max_question_count,default_round_seconds,min_round_seconds,
     max_round_seconds,question_count_editable,round_seconds_editable,max_players,published_at,reviewed_at)
select g.id,1,'WORD_TRANSLATION','PUBLISHED',b.title_ru,b.title_kk,b.description_ru,b.description_kk,
       'Выберите перевод','Аударманы таңдаңыз',b.card_style,b.catalog_order,'NONE','UNIVERSAL',
       10,5,30,20,10,60,true,true,4,current_timestamp,current_timestamp
from quiz_v57_games r join quiz_games g on g.id=r.game_id join quiz_v57_banks b on b.code=g.code;
select v.id,s.id,s.source_language,s.target_language from quiz_v57_games r
join quiz_games g on g.id=r.game_id join quiz_game_versions v on v.game_id=g.id
join vocabulary_sets s on s.code=g.code;
select 'GAME',r.game_id,v.id,'DRAFT','PUBLISHED' from quiz_v57_games r
join quiz_game_versions v on v.game_id=r.game_id;
update quiz_games set published_version_id=(select v.id from quiz_game_versions v where v.game_id=quiz_games.id),
    admin_revision=admin_revision+1,updated_at=current_timestamp where id in(select game_id from quiz_v57_games);

-- Скрытие прежних числовых карточек сохраняет их версии и всю историю комнат.
select g.id,false from quiz_games g where g.code in ('starter-en-numbers-v1','starter-kk-numbers-v1')
  and g.catalog_visible=true and g.status<>'ARCHIVED'
  and (select count(*) from quiz_games x join quiz_v57_banks b on b.code=x.code
       where x.status='PUBLISHED' and x.published_version_id is not null)=3;
update quiz_games set catalog_visible=false,visibility_updated_by=null,visibility_updated_at=current_timestamp,
    admin_revision=admin_revision+1,updated_at=current_timestamp
where code in ('starter-en-numbers-v1','starter-kk-numbers-v1') and catalog_visible=true and status<>'ARCHIVED'
  and (select count(*) from quiz_games x join quiz_v57_banks b on b.code=x.code
       where x.status='PUBLISHED' and x.published_version_id is not null)=3;

drop table quiz_v57_games;
drop table quiz_v57_ready;
drop table quiz_v57_words;
drop table quiz_v57_banks;
